  "intro": "**整章只讲一件事：给感性负载并联电容，把功率因数拉上去。**\n45 题围着这一件事的**为什么、怎么接、怎么看数字、怎么别把自己电死**四个面转。\n\n**先把这一段读懂，后面全是它的展开：**\n电动机、变压器、镇流器这些带线圈的东西是**感性负载**，电流**滞后**电压。\n它们要一份「有功」（真干活的）还要吞一份「无功」（在电源和线圈之间来回荡的）。\n无功不干活，但**它照样占着导线和变压器的容量、照样在线路上发热**。\n电容器的电流**超前**电压，正好和感性的反着来 —— 并在一起两下抵消，\n无功就在电容器和负载之间就地打转，不再跑回电网。结果：\n**功率因数 cosφ 变大 → 同样的有功、线路电流变小 → 线损小、压降小、变压器能带更多设备。**\n\n**⚠ 全章最要命的一句话：电容器断电之后仍然带着电荷，必须充分放电才能碰。**\n这条在 11-E 组一口气考了五道题。",
